export function createPayment(input: PaymentInput): PaymentResult {
  return {
    id: `pay_${input.orderId}`,
    status: input.amountCents > 0 ? 'created' : 'failed',
    redirectUrl: `/checkout/${input.orderId}`,
  }
}

operations.replace:
export function createPayment(input: PaymentInput | string): PaymentResult {
  const orderId = typeof input === 'string' ? input : input.orderId
  const amountCents = typeof input === 'string' ? 0 : input.amountCents

  return {
    id: `pay_${orderId}`,
    status: amountCents > 0 ? 'created' : 'failed',
    redirectUrl: `/checkout/${orderId}`,
  }
}
